module pipelined_skid_buffer(input clock,rst,input [3:0] i_data,input i_valid,output ready_o,valid_o,output [3:0] data_o,input ready_i);
wire [3:0] d0,d1,d2;wire v0,v1,v2,r0,r1,r2;
skid_buffer skid_0(clock,rst,i_data,i_valid,ready_o,d0,v0,r0);
register reg1(clock,rst,d0,v0,r0,v1,d1,r1);
skid_buffer skid_2(clock,rst,d1,v1,r1,d2,v2,r2);
register reg3(clock,rst,d2,v2,r2,valid_o,data_o,ready_i);
endmodule
module register(input clk,rst,input [3:0] i_datan,input i_validn,output ready_out,valid_out,output [3:0] data_out,input ready_in);
reg [3:0] mem;reg data_present;
assign ready_out=!data_present || ready_in;assign valid_out=data_present;assign data_out=mem;
always @(posedge clk or posedge rst)if(rst)begin mem<=0;data_present<=0;end
else if(ready_out)begin data_present<=i_validn;if(i_validn)mem<=i_datan;end
endmodule
module skid_buffer(input clk,reset,input [3:0] i_data,input i_valid,output o_ready,output [3:0] o_data,output o_valid,input i_ready);
reg full;reg [3:0] data_reg;
assign o_ready=!full;assign o_valid=full || i_valid;assign o_data=full?data_reg:i_data;
always @(posedge clk or posedge reset)if(reset)begin full<=0;data_reg<=0;end
else if(full)begin if(i_ready)full<=0;end
else if(i_valid && !i_ready)begin full<=1;data_reg<=i_data;end
endmodule

module cvdp_copilot_apb_gpio #(parameter GPIO_WIDTH=8)(input pclk,preset_n,psel,input [7:2] paddr,input penable,pwrite,input [31:0] pwdata,input [GPIO_WIDTH-1:0] gpio_in,output reg [31:0] prdata,output pready,pslverr,output reg [GPIO_WIDTH-1:0] gpio_out,gpio_enable,output [GPIO_WIDTH-1:0] gpio_int,output comb_int);
reg [GPIO_WIDTH-1:0] sync1,sync2,old,ie,itype,polarity;
assign pready=1;assign pslverr=0;
reg [GPIO_WIDTH-1:0] pending_edges;
wire [GPIO_WIDTH-1:0] edges=ie & itype & ((~polarity & sync2 & ~old)|(polarity & ~sync2 & old));
wire [GPIO_WIDTH-1:0] clear_edges=(psel && penable && pwrite && paddr==6)?GPIO_WIDTH'(pwdata):'0;
always @(posedge pclk or negedge preset_n)
 if(!preset_n)pending_edges<=0;else pending_edges<=(pending_edges & ~clear_edges)|edges;
assign gpio_int=ie & ((itype & pending_edges)|(~itype & (sync2 ^ polarity)));
assign comb_int=|gpio_int;
always @(posedge pclk or negedge preset_n)begin
 if(!preset_n)begin gpio_out<=0;gpio_enable<=0;sync1<=0;sync2<=0;old<=0;ie<=0;itype<=0;polarity<=0;end
 else begin sync1<=gpio_in;sync2<=sync1;old<=sync2;
 if(psel && penable && pwrite)case(paddr)
 1:gpio_out<=GPIO_WIDTH'(pwdata);2:gpio_enable<=GPIO_WIDTH'(pwdata);3:ie<=GPIO_WIDTH'(pwdata);4:itype<=GPIO_WIDTH'(pwdata);5:polarity<=GPIO_WIDTH'(pwdata);
 endcase
 end
end
always @*begin
 prdata=0;if(psel && !pwrite)case(paddr)
 0:prdata=32'(sync2);1:prdata=32'(gpio_out);2:prdata=32'(gpio_enable);3:prdata=32'(ie);4:prdata=32'(itype);5:prdata=32'(polarity);6:prdata=32'(gpio_int);
 endcase
end
endmodule
